//! Public API consumer for independently authored observation fixtures.
//! No expected fixture bytes are generated by this executable. `observe` reports actual
//! results; `self-test` compares them with the checked-in independent expected data.
use serde_json::{Value, json};
use stateless::observation::{
    EncodedPayloads, Event, LogLevel, NoPayloads, ObservationOptions, Observer,
    PayloadFormat, SnapshotPolicy, TextObserver,
};
use stateless::trace::RunConfig;
use stateless::{
    Check, Disposition, EncodeBuffer, Model, ModelCodec, ModelError, ModelMetadata,
    Transition, TransitionRef,
};
use std::cell::RefCell;
use std::io::{self, Write};
use std::num::NonZeroU64;
use std::rc::Rc;

type Result<T> = std::result::Result<T, String>;

struct FixtureModel {
    callbacks: Rc<RefCell<Vec<String>>>,
    fault: Rc<RefCell<String>>,
}

impl Model for FixtureModel {
    type State = u8;
    type Input = u8;
    type Output = u8;
    fn metadata(&self) -> ModelMetadata {
        panic!("diagnostic observation must use supplied metadata")
    }
    fn initial_state(&self) -> std::result::Result<u8, ModelError> {
        panic!("diagnostic observation must not initialize a model")
    }
    fn step(&self, _: &u8, _: &u8) -> std::result::Result<Transition<u8, u8>, ModelError> {
        panic!("diagnostic observation must not execute a reducer")
    }
    fn check_state(&self, _: &u8) -> std::result::Result<Vec<Check>, ModelError> {
        panic!("diagnostic observation must not run state checks")
    }
    fn check_transition(
        &self,
        _: &u8,
        _: &u8,
        _: &TransitionRef<'_, u8, u8>,
    ) -> std::result::Result<Vec<Check>, ModelError> {
        panic!("diagnostic observation must not run transition checks")
    }
}

impl FixtureModel {
    fn encode(
        &self,
        stage: &str,
        value: u8,
        out: &mut EncodeBuffer<'_>,
    ) -> std::result::Result<(), ModelError> {
        self.callbacks.borrow_mut().push(format!("{stage}:{value}"));
        if *self.fault.borrow() == stage {
            return Err(ModelError::new("fixture codec failure"));
        }
        out.extend_from_slice(&[value])
    }
}

impl ModelCodec for FixtureModel {
    fn encode_state(&self, _: &u8) -> std::result::Result<Vec<u8>, ModelError> {
        panic!("EncodedPayloads must dispatch the bounded state override")
    }
    fn encode_input(&self, _: &u8) -> std::result::Result<Vec<u8>, ModelError> {
        panic!("EncodedPayloads must dispatch the bounded input override")
    }
    fn encode_output(&self, _: &u8) -> std::result::Result<Vec<u8>, ModelError> {
        panic!("EncodedPayloads must dispatch the bounded output override")
    }
    fn decode_state(&self, _: &[u8]) -> std::result::Result<u8, ModelError> {
        panic!("diagnostic observation must not decode")
    }
    fn decode_input(&self, _: &[u8]) -> std::result::Result<u8, ModelError> {
        panic!("diagnostic observation must not decode")
    }
    fn encode_state_into(&self, value: &u8, out: &mut EncodeBuffer<'_>) -> std::result::Result<(), ModelError> {
        self.encode("encode_state", *value, out)
    }
    fn encode_input_into(&self, value: &u8, out: &mut EncodeBuffer<'_>) -> std::result::Result<(), ModelError> {
        self.encode("encode_input", *value, out)
    }
    fn encode_output_into(&self, value: &u8, out: &mut EncodeBuffer<'_>) -> std::result::Result<(), ModelError> {
        self.encode("encode_output", *value, out)
    }
}

enum FixturePayloads {
    None(NoPayloads),
    Encoded(EncodedPayloads),
    Custom(String),
}

fn custom(model: &FixtureModel, stage: &str, value: u8, text: &str, out: &mut dyn Write) -> io::Result<()> {
    model.callbacks.borrow_mut().push(format!("{stage}:{value}"));
    if *model.fault.borrow() == stage {
        return Err(io::Error::other(stage.to_owned()));
    }
    if stage == "format_input" && *model.fault.borrow() == "swallow_input" {
        let _ = out.write_all(&[b'x'; 1024]);
        return Ok(());
    }
    out.write_all(text.as_bytes())
}

impl PayloadFormat<FixtureModel> for FixturePayloads {
    fn state(&mut self, m: &FixtureModel, v: &u8, out: &mut dyn Write) -> io::Result<()> {
        match self {
            Self::None(f) => f.state(m, v, out),
            Self::Encoded(f) => f.state(m, v, out),
            Self::Custom(text) => custom(m, "format_state", *v, text, out),
        }
    }
    fn input(&mut self, m: &FixtureModel, v: &u8, out: &mut dyn Write) -> io::Result<()> {
        match self {
            Self::None(f) => f.input(m, v, out),
            Self::Encoded(f) => f.input(m, v, out),
            Self::Custom(text) => custom(m, "format_input", *v, text, out),
        }
    }
    fn output(&mut self, m: &FixtureModel, v: &u8, out: &mut dyn Write) -> io::Result<()> {
        match self {
            Self::None(f) => f.output(m, v, out),
            Self::Encoded(f) => f.output(m, v, out),
            Self::Custom(text) => custom(m, "format_output", *v, text, out),
        }
    }
}

#[derive(Default)]
struct FixtureWriter {
    bytes: Vec<u8>,
    fail_after: Option<usize>,
    fail_flush: bool,
    writes: usize,
    flushes: usize,
}

impl Write for FixtureWriter {
    fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
        self.writes += 1;
        let remaining = self.fail_after.map(|n| n.saturating_sub(self.bytes.len()));
        if remaining == Some(0) {
            return Err(io::Error::other("sink_write"));
        }
        let count = remaining.unwrap_or(bytes.len()).min(bytes.len());
        self.bytes.extend_from_slice(&bytes[..count]);
        Ok(count)
    }
    fn flush(&mut self) -> io::Result<()> {
        self.flushes += 1;
        if self.fail_flush { Err(io::Error::other("sink_flush")) } else { Ok(()) }
    }
}

fn field<'a>(value: &'a Value, key: &str) -> Result<&'a Value> {
    value.get(key).ok_or_else(|| format!("missing {key}"))
}
fn string(value: &Value) -> Result<&str> {
    value.as_str().ok_or_else(|| "expected string".into())
}
fn text<'a>(value: &'a Value, key: &str) -> Result<&'a str> {
    string(field(value, key)?)
}
fn array(value: &Value) -> Result<&[Value]> {
    value.as_array().map(Vec::as_slice).ok_or_else(|| "expected array".into())
}
fn u64_text(value: &Value) -> Result<u64> {
    let s = string(value)?;
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return Err("expected decimal u64 string".into());
    }
    s.parse().map_err(|_| "u64 out of range".into())
}
fn integer(value: &Value) -> Result<usize> {
    usize::try_from(value.as_u64().ok_or("expected unsigned integer")?)
        .map_err(|_| "integer out of range".into())
}
fn code(value: &Value) -> Result<u8> {
    u8::try_from(integer(value)?).map_err(|_| "payload code out of range".into())
}
fn level(value: &Value) -> Result<LogLevel> {
    match string(value)? {
        "Off" => Ok(LogLevel::Off), "Error" => Ok(LogLevel::Error),
        "Warn" => Ok(LogLevel::Warn), "Info" => Ok(LogLevel::Info),
        "Debug" => Ok(LogLevel::Debug), "Trace" => Ok(LogLevel::Trace),
        _ => Err("unknown log level".into()),
    }
}
fn snapshots(value: &Value) -> Result<SnapshotPolicy> {
    match value.as_str() {
        Some("None") => Ok(SnapshotPolicy::None),
        Some("EveryTransition") => Ok(SnapshotPolicy::EveryTransition),
        None => Ok(SnapshotPolicy::Every(NonZeroU64::new(u64_text(field(value, "every")?)?)
            .ok_or("snapshot period must be positive")?)),
        _ => Err("unknown snapshot policy".into()),
    }
}
fn checks(value: &Value) -> Result<Vec<Check>> {
    array(value)?.iter().map(|c| {
        let id = text(c, "id")?.to_owned();
        match text(c, "status")? {
            "Passed" => Ok(Check::passed(id)),
            "Failed" => Ok(Check::failed(id, text(c, "message")?)),
            "Skipped" => Ok(Check::skipped(id, text(c, "message")?)),
            _ => Err("unknown check status".into()),
        }
    }).collect()
}
fn disposition(value: &Value) -> Result<Disposition> {
    match text(value, "kind")? {
        "Accepted" => Ok(Disposition::Accepted),
        "Rejected" => Ok(Disposition::Rejected(text(value, "reason")?.into())),
        "Ignored" => Ok(Disposition::Ignored(text(value, "reason")?.into())),
        _ => Err("unknown disposition".into()),
    }
}
fn error_stage(error: &io::Error) -> Result<String> {
    let message = error.to_string();
    if message == "observation record exceeds byte limit" {
        return Ok("record_limit".into());
    }
    if message == "observation sink failed; output may be incomplete" {
        return Ok("sink_poisoned".into());
    }
    for stage in ["input", "output", "state"] {
        if message.starts_with(&format!("encode {stage}:")) {
            return Ok(format!("encode_{stage}"));
        }
    }
    if ["format_input", "format_output", "format_state", "sink_write", "sink_flush"].contains(&message.as_str()) {
        return Ok(message);
    }
    Err(format!("unclassified observation error: {message}"))
}

type Logger = TextObserver<FixtureWriter, FixturePayloads>;
fn event(log: &mut Logger, model: &FixtureModel, e: &Value) -> Result<io::Result<()>> {
    Ok(match text(e, "kind")? {
        "set_level" => { log.set_level(level(field(e, "level")?)?); Ok(()) }
        "set_snapshots" => { log.set_snapshots(snapshots(field(e, "snapshots")?)?); Ok(()) }
        "flush" => log.flush(),
        "transition" => {
            let before = code(field(e, "before")?)?;
            let input = code(field(e, "input")?)?;
            let transition = Transition {
                state: code(field(e, "state")?)?,
                outputs: array(field(e, "outputs")?)?.iter().map(code).collect::<Result<_>>()?,
                disposition: disposition(field(e, "disposition")?)?,
            };
            let checks = checks(field(e, "checks")?)?;
            log.observe(model, Event::Transition {
                sequence: NonZeroU64::new(u64_text(field(e, "sequence")?)?)
                    .ok_or("transition sequence must be positive")?,
                before: &before, input: &input, transition: transition.as_ref(), checks: &checks,
            })
        }
        "checkpoint" => {
            let state = code(field(e, "state")?)?;
            let checks = checks(field(e, "checks")?)?;
            log.observe(model, Event::Checkpoint {
                sequence: u64_text(field(e, "sequence")?)?, state: &state, checks: &checks,
            })
        }
        "message" => {
            let sequence = field(e, "sequence")?;
            log.observe(model, Event::Message {
                level: level(field(e, "level")?)?,
                sequence: if sequence.is_null() { None } else { Some(u64_text(sequence)?) },
                message: text(e, "message")?,
            })
        }
        "finished" => log.observe(model, Event::Finished {
            transitions: u64_text(field(e, "transitions")?)?, reason: text(e, "reason")?,
        }),
        "started" => {
            let m = field(e, "metadata")?;
            let version = |key| -> Result<u32> {
                u32::try_from(integer(field(m, key)?)?).map_err(|_| "version out of range".into())
            };
            let metadata = ModelMetadata {
                name: text(m, "name")?.into(), model_version: version("model_version")?,
                properties_version: version("properties_version")?, codec_version: version("codec_version")?,
                build: text(m, "build")?.into(),
            };
            let c = field(e, "config")?;
            let seed = field(c, "seed")?;
            let parameters = array(field(c, "parameters")?)?.iter().map(|pair| {
                let pair = array(pair)?;
                if pair.len() != 2 { return Err("expected parameter pair".into()); }
                Ok((string(&pair[0])?.to_owned(), string(&pair[1])?.to_owned()))
            }).collect::<Result<Vec<_>>>()?;
            let config = RunConfig {
                strategy: text(c, "strategy")?.into(),
                seed: if seed.is_null() { None } else { Some(u64_text(seed)?) }, parameters,
            };
            log.observe(model, Event::Started { metadata: &metadata, config: &config })
        }
        _ => return Err("unknown event kind".into()),
    })
}

fn observe(case: &Value) -> Result<Value> {
    let id = text(case, "id")?;
    if let Some(binding) = case.get("binding") {
        if string(binding)? != "declaration" { return Err("unknown binding".into()); }
        // Rust exposes ModelCodec directly; native ports exercise their actual
        // declaration binding wrapper for this same fixture case.
    }
    let model = FixtureModel { callbacks: Rc::new(RefCell::new(vec![])), fault: Rc::new(RefCell::new(String::new())) };
    let o = field(case, "options")?;
    let mut options = ObservationOptions::default();
    if let Some(v) = o.get("level") { options.level = level(v)?; }
    if let Some(v) = o.get("snapshots") { options.snapshots = snapshots(v)?; }
    if let Some(v) = o.get("max_record_bytes") { options.max_record_bytes = integer(v)?; }
    let p = field(case, "payloads")?;
    let payloads = match text(p, "kind")? {
        "none" => FixturePayloads::None(NoPayloads),
        "encoded" => FixturePayloads::Encoded(EncodedPayloads::new(integer(field(p, "max_blob_bytes")?)?)),
        "custom" => FixturePayloads::Custom(text(p, "text")?.into()),
        _ => return Err("unknown payload formatter".into()),
    };
    let mut writer = FixtureWriter::default();
    if let Some(sink) = case.get("sink") {
        if let Some(v) = sink.get("fail_after_bytes") { writer.fail_after = Some(integer(v)?); }
        if let Some(v) = sink.get("fail_flush") { writer.fail_flush = v.as_bool().ok_or("expected boolean")?; }
    }
    let mut log = TextObserver::new(writer, text(case, "stream")?, options, payloads);
    let mut first_error: Option<String> = None;
    for e in array(field(case, "events")?)? {
        *model.fault.borrow_mut() = e.get("fault").map(string).transpose()?.unwrap_or("").into();
        let writes = log.get_ref().writes;
        let flushes = log.get_ref().flushes;
        if let Err(error) = event(&mut log, &model, e)? {
            let stage = error_stage(&error)?;
            if (stage == "record_limit" || stage.starts_with("encode_") || stage.starts_with("format_"))
                && log.get_ref().writes != writes {
                return Err(format!("{id}: formatting failure reached the writer"));
            }
            if stage == "sink_poisoned"
                && (log.get_ref().writes != writes || log.get_ref().flushes != flushes)
            {
                return Err(format!("{id}: poisoned observation reached the writer"));
            }
            first_error.get_or_insert(stage);
        }
    }
    // Health has no public getter. Off is the public no-work health probe, and
    // must still return an error after a sink failure.
    log.set_level(LogLevel::Off);
    let calls_before = (log.get_ref().writes, log.get_ref().flushes, model.callbacks.borrow().len());
    let sink_poisoned = match log.observe(&model, Event::Message { level: LogLevel::Info, sequence: None, message: "health probe" }) {
        Ok(()) => false,
        Err(error) if error_stage(&error)? == "sink_poisoned" => true,
        Err(error) => return Err(format!("{id}: unexpected health probe error: {error}")),
    };
    if calls_before != (log.get_ref().writes, log.get_ref().flushes, model.callbacks.borrow().len()) {
        return Err(format!("{id}: Off health probe performed callback or sink work"));
    }
    let flushes = log.get_ref().flushes;
    let writer = log.into_inner();
    if writer.flushes != flushes { return Err(format!("{id}: extraction implicitly flushed")); }
    let record_hex: String = writer.bytes.iter().map(|b| format!("{b:02x}")).collect();
    let callbacks = model.callbacks.borrow().clone();
    Ok(json!({"id": id, "record_hex": record_hex, "callbacks": callbacks,
        "error_stage": first_error, "sink_poisoned": sink_poisoned}))
}

fn run() -> Result<Value> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    let [mode, path] = args.as_slice() else { return Err("expected observe|self-test fixturePath".into()); };
    if mode != "observe" && mode != "self-test" { return Err("expected observe|self-test fixturePath".into()); }
    let fixture: Value = serde_json::from_slice(&std::fs::read(path).map_err(|e| e.to_string())?)
        .map_err(|e| e.to_string())?;
    if text(&fixture, "schema")? != "statelessness.observation.v1" { return Err("wrong fixture schema".into()); }
    let mut results = vec![];
    let mut ids = std::collections::BTreeSet::new();
    let cases = array(field(&fixture, "cases")?)?;
    if cases.is_empty() { return Err("empty observation corpus".into()); }
    for case in cases {
        let id = text(case, "id")?;
        if !ids.insert(id) { return Err(format!("duplicate case id: {id}")); }
        let actual = observe(case).map_err(|e| format!("{id}: {e}"))?;
        if mode == "self-test" {
            let e = field(case, "expected")?;
            let expected = json!({"id": id, "record_hex": field(e, "record_hex")?,
                "callbacks": field(e, "callbacks")?, "error_stage": field(e, "error_stage")?,
                "sink_poisoned": field(e, "sink_poisoned")?});
            if actual != expected { return Err(format!("{id}: expected {expected}; actual {actual}")); }
        }
        results.push(actual);
    }
    Ok(json!({"schema": "statelessness.observation-results.v1", "language": "rust", "cases": results}))
}

fn main() {
    match run() {
        Ok(value) => println!("{value}"),
        Err(error) => { eprintln!("{error}"); std::process::exit(1); }
    }
}
